import{_ as t,o,c as a,a2 as r}from"./chunks/framework.il0noOp3.js";const g=JSON.parse('{"title":"AzureScout v3.0.0","description":"AzureScout v3.0.0 release architecture, migration notes, and verification evidence.","frontmatter":{"description":"AzureScout v3.0.0 release architecture, migration notes, and verification evidence."},"headers":[],"relativePath":"project/releases/v3.0.0.md","filePath":"project/releases/v3.0.0.md"}'),i={name:"project/releases/v3.0.0.md"};function c(n,e,l,s,d,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="azurescout-v3-0-0" tabindex="-1">AzureScout v3.0.0 <a class="header-anchor" href="#azurescout-v3-0-0" aria-label="Permalink to &quot;AzureScout v3.0.0&quot;">​</a></h1><p>Version 3 replaces the retired per-collector PowerShell source tree with the declarative catalog under <code>manifests/collectors</code>. Production discovery, processing, and reporting execute that catalog only; there is no imperative fallback or environment-variable kill switch.</p><h2 id="what-changed" tabindex="-1">What changed <a class="header-anchor" href="#what-changed" aria-label="Permalink to &quot;What changed&quot;">​</a></h2><ul><li>174 collector definitions are discovered directly from <code>manifests/collectors</code>.</li><li>The legacy <code>Modules/Public/InventoryModules</code> tree has been removed.</li><li>Collector execution remains under <code>Set-StrictMode -Version Latest</code>.</li><li>Collector output is pinned by committed golden records: rows in order and worksheet cells for both tag modes.</li><li>The deterministic processing pipeline uses the same manifest catalog in production and tests.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>The release gate consists of the following evidence:</p><ul><li>174/174 direct declarative collectors execute against optional-property fixtures under StrictMode.</li><li>174/174 golden row contracts pass.</li><li>348/348 golden workbook contracts pass (tag and no-tag export for every collector).</li><li>15 category-level manifest module checks pass independently.</li><li>The catalog validator accepts all 174 definitions without requiring a legacy source file.</li></ul><h2 id="migration-notes" tabindex="-1">Migration notes <a class="header-anchor" href="#migration-notes" aria-label="Permalink to &quot;Migration notes&quot;">​</a></h2><p>Users do not need to change <code>Invoke-AzureScout</code> commands or category names. Contributors add or change a collector definition in <code>manifests/collectors/&lt;Category&gt;/&lt;Name&gt;.psd1</code>, update its fixture and golden record, and run the catalog and golden tests. Do not add a <code>.ps1</code> collector fallback.</p><p>See <a href="./../../reference/category-reference.html">Category Reference</a> for category names and <a href="./../testing.html">Testing</a> for the release gates.</p>',10)])])}const p=t(i,[["render",c]]);export{g as __pageData,p as default};
